import{_ as a,o,c as e,ai as s}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"在自己电脑上干活","description":"什么时候让 Bot 在你本地电脑上执行命令、如何授权，以及最稳妥的设置。","frontmatter":{"related":["/basics/safety-approvals","/basics/cloud-computer","/roles/developers"],"title":"在自己电脑上干活","description":"什么时候让 Bot 在你本地电脑上执行命令、如何授权，以及最稳妥的设置。","section":"basics","order":6,"tags":["基础","本地电脑","授权","安全"],"sources":["https://docs.x.ai/grok-bot/approvals-security-and-privacy","https://cursor.com/docs/grok-bot/work"],"wordCount":795,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"在自己电脑上干活 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"什么时候让 Bot 在你本地电脑上执行命令、如何授权，以及最稳妥的设置。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/basics/local-computer"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/basics-local-computer-e771a39b79.png"}],["meta",{"property":"og:image:alt","content":"在自己电脑上干活 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"在自己电脑上干活 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"什么时候让 Bot 在你本地电脑上执行命令、如何授权，以及最稳妥的设置。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/basics-local-computer-e771a39b79.png"}],["meta",{"name":"twitter:image:alt","content":"在自己电脑上干活 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/basics/local-computer"}]]},"headers":[],"relativePath":"basics/local-computer.md","filePath":"basics/local-computer.md","lastUpdated":1792571830000}'),l={name:"basics/local-computer.md"};function n(i,t,p,r,c,d){return o(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="在自己电脑上干活" tabindex="-1">在自己电脑上干活 <a class="header-anchor" href="#在自己电脑上干活" aria-label="Permalink to &quot;在自己电脑上干活&quot;">​</a></h1><p>默认情况下，Bot 只在它的云电脑上工作，碰不到你面前这台 Mac 或 Windows 电脑。但有时候，资料就在你本地：一个没上传的项目文件夹、一份只存在本机的表格、一个需要在本地跑的脚本。这时可以让 Bot 在你注册过的本地电脑上干活，<strong>前提是你同意</strong>。</p><h2 id="授权方式" tabindex="-1">授权方式 <a class="header-anchor" href="#授权方式" aria-label="Permalink to &quot;授权方式&quot;">​</a></h2><p>在设置里可以找到&quot;在本地电脑上执行&quot;这类选项（具体位置随版本变化，以官方最新说明为准），通常有三档：</p><ul><li><strong>每次都问</strong>（默认）：每条命令都弹出确认，你看清再放行。</li><li><strong>始终允许</strong>：不再逐条询问。</li><li><strong>从不允许</strong>：彻底关闭。</li></ul><p>注册了多台电脑后，可以给每台单独设置。如果你在团队里，管理员可能设置了上限，团队策略更严格时以团队为准。</p><div class="tip custom-block"><p class="custom-block-title">推荐设置</p><p>平时设为&quot;从不允许&quot;或&quot;每次都问&quot;。只有在某个任务确实需要本地文件时才放行，用完再收紧。</p></div><h2 id="什么时候值得用" tabindex="-1">什么时候值得用 <a class="header-anchor" href="#什么时候值得用" aria-label="Permalink to &quot;什么时候值得用&quot;">​</a></h2><ul><li>需要读取只存在于本地的文件，又不方便上传。</li><li>要在本地开发环境里跑测试或构建。</li><li>要把 Bot 做好的文件直接放到你本地某个文件夹。</li></ul><h2 id="更省心的替代方案" tabindex="-1">更省心的替代方案 <a class="header-anchor" href="#更省心的替代方案" aria-label="Permalink to &quot;更省心的替代方案&quot;">​</a></h2><p>很多时候不必开放本地执行：</p><ul><li><strong>文件搬运</strong>：让 Bot 把本地文件复制到云电脑处理，处理完再复制回来。复制过程同样需要你批准。</li><li><strong>直接上传</strong>：把文件拖进对话。</li><li><strong>网盘中转</strong>：放在已连接的网盘里，让 Bot 去取。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把我本地&quot;文档/合同&quot;文件夹里 2026 年的 PDF 复制到云电脑上，</span></span>
<span class="line"><span>提取每份合同的甲方、金额、到期日，做成一张表。处理时只读，不要改本地任何文件。</span></span></code></pre></div><h2 id="电脑息屏后-bot-连不上了" tabindex="-1">电脑息屏后，Bot 连不上了？ <a class="header-anchor" href="#电脑息屏后-bot-连不上了" aria-label="Permalink to &quot;电脑息屏后，Bot 连不上了？&quot;">​</a></h2><p>Bot 要用你的电脑，前提是这台电脑醒着、Grok Bot App 在运行。Mac 上有两件事要一起做：</p><ol><li><strong>让系统别睡</strong>：系统设置 → 电池 → 选项，打开&quot;接电源且显示器关闭时防止自动睡眠&quot;一类的开关（不同 macOS 版本措辞略有差异），并且接着电源、不要合盖。</li><li><strong>关掉 Grok Bot App 的 App Nap</strong>：macOS 会让&quot;不在前台&quot;的 App 小睡，App 一睡，云端的 Bot 就够不着你的电脑。只做第 1 步往往不够。</li></ol><p>第 2 步可以直接让 Bot 来做（命令会先给你看）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>查出我 Mac 上 Grok Bot App 的 bundle id，用 defaults write 把它的 App Nap 关掉，</span></span>
<span class="line"><span>执行前把命令给我看，做完告诉我要不要重启 App。</span></span></code></pre></div><p>只想&quot;跑任务那段时间别睡&quot;，可以在命令前加系统自带的 <code>caffeinate -i</code>，任务结束就失效。要让本机长任务跑完再接到通知，见日更<a href="/daily/2026-10-21-wake-on-done">Wake on Done：Bot 派出去的长任务一跑完，自动把它叫醒</a>。</p><h2 id="批准前看清楚" tabindex="-1">批准前看清楚 <a class="header-anchor" href="#批准前看清楚" aria-label="Permalink to &quot;批准前看清楚&quot;">​</a></h2><p>当弹出命令确认时，花几秒看三件事：</p><ol><li><strong>命令要做什么</strong>：读取、写入，还是删除？</li><li><strong>作用在哪里</strong>：哪个文件夹？会不会波及整个磁盘？</li><li><strong>为什么需要</strong>：和你交代的任务是否相关？</li></ol><p>看不懂就别批，先问：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这条命令具体会做什么？会修改或删除哪些文件？用大白话解释一下。</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">本地执行的权限是全局的</p><p>&quot;始终允许&quot;会对你所有的 Bot 生效，而不只是当前这个。除非你非常清楚自己在做什么，否则不要长期开着。</p></div>`,25)])])}const h=a(l,[["render",n]]);export{g as __pageData,h as default};
